<?php use App\Domain\Quotes\QuoteRules; ?>
<section class="admin-page-head"><div><p class="admin-kicker">M08 · OPERACIÓN COMERCIAL</p><h1>Cotizaciones</h1><p>Documentos históricos por sucursal, con precios e impuestos configurados.</p></div><?php if($capabilities['quotes.create']??false):?><a class="admin-primary-button" href="/admin/quotes/create">+ Nueva cotización</a><?php endif?></section>
<form class="admin-panel admin-filter-bar" method="get"><label class="admin-field"><span>Buscar folio o cliente</span><input name="q" type="search" maxlength="120" value="<?= e($q) ?>"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="">Todos</option><?php foreach(QuoteRules::LABELS as $key=>$label):?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label><button class="admin-secondary-button">Aplicar filtros</button></form>
<section class="admin-panel admin-table-panel"><?php if(!$page->items):?><div class="admin-empty"><strong>Aún no hay cotizaciones</strong><span>Comienza seleccionando una sucursal y un cliente registrado. No se generan documentos de ejemplo.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Documento</th><th>Cliente</th><th>Sucursal / vendedor</th><th>Vigencia</th><th>Estado</th><th>Total MXN</th><th></th></tr></thead><tbody><?php foreach($page->items as $qrow):?><tr><td data-label="Documento"><strong><?= e($qrow['folio']) ?></strong><small>Versión <?= e($qrow['current_version']) ?> · <?= e($qrow['created_at']) ?> UTC</small></td><td data-label="Cliente"><?= e($qrow['customer_name']) ?></td><td data-label="Sucursal / vendedor"><?= e($qrow['branch_name']) ?><small><?= e($qrow['seller_name']??'Sin asignar') ?></small></td><td data-label="Vigencia"><?= e($qrow['valid_until']) ?></td><td data-label="Estado"><span class="admin-status"><?= e(QuoteRules::LABELS[$qrow['status']]??$qrow['status']) ?></span></td><td data-label="Total MXN"><strong>$<?= e($qrow['total']) ?></strong></td><td><a class="admin-secondary-button" href="/admin/quotes/detail?id=<?= e($qrow['id']) ?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div><nav class="admin-pagination" aria-label="Paginación"><?php $params=['q'=>$q,'status'=>$status,'branch_id'=>$branchId];if($page->offset>0):?><a class="admin-secondary-button" href="?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a class="admin-secondary-button" href="?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></section>
